<script setup lang="ts">
import PhotoFieldMobile from './PhotoFieldMobile.vue';
import PhotoGridMobile from './PhotoGridMobile.vue';
import { api } from '../platform';
import { computed, ref, watch } from 'vue';
import ForumAudioMobile from './ForumAudioMobile.vue';
import ForumAudioFieldMobile from './ForumAudioFieldMobile.vue';
import { type Row, forumCategories, statusNames, formatTime } from '../../../shared/domain';
import { useForum } from '../../../shared/useForum';
import { RAILWAY_BOARD, railwayDiscussionTypes, safeForumSourceUrl } from '../../../shared/railwayForum';
const props = defineProps<{ user: Row | null; focus?: Row | null; board?: string; title?: string; intro?: string; embedded?: boolean; active?: boolean }>();const emit = defineEmits<{ (event: 'join'): void }>();
const { managed,managedReplies,restrictions,blocks,selected,replies,tab,category,query,discussionType,sort,lockedBoard,railwayMode,error,message,busy,creating,form,reply,replyAudio,replyPhotos,quoted,operation,note,moderator,visible,load,detail,create,post,respond,ask,perform } = useForum(() => props.user,api,() => props.board || '');
const sourceUrl = computed(() => safeForumSourceUrl(selected.value?.sourceUrl));
const focused = ref<Row | null>(null);
watch(() => [props.board, props.user?.id], () => { focused.value = null; });
watch(() => props.focus, row => { focused.value = row || null;if (!row) return;if (row.manage) { selected.value = null;tab.value = 'manage'; }else detail({ id: row.topicId || row.id }); }, { immediate: true });
function focusRows(rows: Row[], kind: string) { return focused.value?.manage ? rows.filter(row => focused.value?.kind === kind && row.id === focused.value?.id) : rows; }
const audioUploading = ref(false), photosPending = ref(false);
watch(() => [creating.value, selected.value?.id, props.user?.id, props.board], () => { audioUploading.value = false;photosPending.value = false; });
function newTopic(source?: Row) { if (props.user?.status !== 'approved') emit('join');else create(source); }
function changeBoard(event: any) { form.value.category = forumCategories[Number(event.detail.value)]; }
function changeDiscussionType(event: any) { form.value.discussionType = railwayDiscussionTypes[Number(event.detail.value)]; }
const sortOptions = [{ id: 'latest', label: '最新发布' }, { id: 'replies', label: '最多回复' }, { id: 'unanswered', label: '待回复' }];
function changeSort(event: any) { sort.value = sortOptions[Number(event.detail.value)].id; }
function openSource() {
  if (!sourceUrl.value) return;
  // #ifdef H5
  window.open(sourceUrl.value, '_blank', 'noopener,noreferrer');
  // #endif
  // #ifdef MP-WEIXIN
  uni.setClipboardData({ data: sourceUrl.value, success: () => uni.showToast({ title: '来源链接已复制', icon: 'none' }) });
  // #endif
}
</script>
<template><view class="forum-mobile" :class="{ 'forum-embedded': embedded }"><view v-if="!creating && !selected && !operation" class="forum-heading"><view class="forum-heading-copy"><view class="title" role="heading" :aria-level="embedded ? 2 : 1">{{ title || '老乡论坛' }}</view><view class="intro">{{ embedded ? '新帖与回复审核后公开' : intro || '有问题就问，看到熟悉的话题也可以回一句。' }}</view></view><button v-if="embedded" class="primary" @click="newTopic()">＋ 发起话题</button></view><view v-if="error" class="error">{{ error }}</view><view v-if="message" class="notice-line">{{ message }}</view>
<view v-if="operation" class="form-page"><button class="text-button" :disabled="busy" @click="operation = null">← 返回</button><view class="form-title">{{ operation.title }}</view><view class="meta">{{ operation.row.title || operation.row.authorName || operation.row.name }}</view><view v-if="operation.action === 'delete'" class="safe-note">确认后正文将清空，楼层与必要处理记录保留。</view><view v-if="!['approved','block','unblock','lock','pin','unpin','hot','unhot'].includes(operation.action)" class="field"><text class="field-label">处理说明（至少2字）</text><textarea v-model="note" maxlength="300"/></view><button class="primary" :disabled="busy" @click="perform">确认操作</button></view>
<view v-else-if="creating" class="form-page"><button class="text-button" @click="creating = false">← 返回论坛</button><view class="form-title">{{ form.forwardedTopicId ? '转发并说说看法' : '发起一个话题' }}</view><view class="field"><text class="field-label">标题</text><input v-model="form.title" maxlength="80"/></view><view v-if="lockedBoard" class="meta">发布到 {{ lockedBoard }}</view><view v-else class="field"><text class="field-label">板块</text><picker :range="forumCategories" @change="changeBoard"><view class="picker-value">{{ form.category }} ▾</view></picker></view><template v-if="(lockedBoard || form.category) === RAILWAY_BOARD"><view class="field"><text class="field-label">话题类型</text><picker :range="railwayDiscussionTypes" :value="Math.max(0,railwayDiscussionTypes.indexOf(form.discussionType))" @change="changeDiscussionType"><view class="picker-value">{{ form.discussionType }} ▾</view></picker></view><view class="field"><text class="field-label">来源名称（选填）</text><input v-model="form.sourceName" maxlength="100" placeholder="如新闻网站、发布单位"/></view><view class="field"><text class="field-label">来源链接（选填）</text><input v-model="form.sourceUrl" maxlength="1000" placeholder="https://"/></view><view class="safe-note">转载消息请同时填写来源名称和原文链接；个人讨论可以留空。</view></template><view class="field"><text class="field-label">分享内容（附照片或语音时选填）</text><textarea v-model="form.content" maxlength="5000" class="topic-textarea"/></view><PhotoFieldMobile v-model="form.photos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioFieldMobile v-model="form.audio" :user-id="user?.id" @busy="audioUploading = $event"/><view class="safe-note">主题和回复经审核后展示；转发保留原帖来源，原帖隐藏后不再展示原文。</view><button class="primary" :disabled="busy || audioUploading || photosPending" @click="post">提交审核</button></view>
<template v-else-if="selected"><button class="text-button" @click="selected = null">← 返回话题列表</button><view class="panel"><text class="tag">{{ selected.category }} · {{ statusNames[selected.status] }}</text><text v-if="selected.pinned && selected.status === 'approved'" class="tag promotion-pin">置顶</text><text v-if="selected.hot && selected.status === 'approved'" class="tag promotion-hot">热帖</text><view class="card-title">{{ selected.title }}</view><view class="meta">楼主 · {{ selected.authorName }} · {{ formatTime(selected.createdAt) }}</view><view v-if="selected.category === RAILWAY_BOARD" class="forum-type">{{ selected.discussionType || railwayDiscussionTypes[0] }}</view><view class="prose topic-body">{{ selected.content }}</view><button v-if="selected.category === RAILWAY_BOARD && selected.sourceName && sourceUrl" class="forum-source-link" @click="openSource">来源：{{ selected.sourceName }} · 查看原文 ↗</button><PhotoGridMobile :photos="selected.photos || []"/><ForumAudioMobile :active="active !== false" v-if="selected.audio" :attachment="selected.audio"/><view v-if="selected.forwarded" class="quoted-post"><view v-if="selected.forwarded.unavailable">原帖已不可见</view><template v-else><text>转发自 {{ selected.forwarded.authorName }}</text><view>{{ selected.forwarded.title }}</view><view>{{ selected.forwarded.content }}</view><PhotoGridMobile :photos="selected.forwarded.photos || []"/><ForumAudioMobile :active="active !== false" v-if="selected.forwarded.audio" :attachment="selected.forwarded.audio"/><button class="text-button" @click="detail(selected.forwarded)">查看原帖 →</button></template></view><view class="button-row"><button v-if="selected.status === 'approved'" class="outline small" @click="newTopic(selected)">转发</button><button v-if="user?.status === 'approved' && selected.authorId !== user.id" class="text-button" @click="ask(selected,'block')">拉黑作者</button><button v-if="!selected.locked && (selected.authorId === user?.id || selected.canModerate)" class="text-button" @click="ask(selected,'lock')">关闭回复</button><button v-if="selected.authorId === user?.id || selected.canModerate" class="text-button" @click="ask(selected,'delete')">删除</button><template v-if="selected.canModerate"><template v-if="selected.status === 'approved'"><button class="text-button" :disabled="busy" @click="ask(selected,selected.pinned ? 'unpin' : 'pin')">{{ selected.pinned ? '取消置顶' : '置顶话题' }}</button><button class="text-button" :disabled="busy" @click="ask(selected,selected.hot ? 'unhot' : 'hot')">{{ selected.hot ? '取消热帖' : '设为热帖' }}</button></template><button v-if="selected.status === 'approved'" class="text-button" @click="ask(selected,'hidden')">隐藏</button><button class="text-button" @click="ask(selected,'mute')">禁言作者</button><button class="text-button" @click="ask(selected,'kick')">移出版块</button></template></view></view><view class="section-title">老乡的回复</view><view v-if="!replies.length" class="empty">还没有回复，来聊几句吧。</view><view v-for="(row,index) in replies" :key="row.id" class="panel"><view class="row"><text>{{ row.authorName }}</text><text class="meta">{{ row.floor || index + 1 }} 楼 · {{ statusNames[row.status] }}</text></view><view v-if="row.quoted" class="quoted-post"><text v-if="row.quoted.unavailable">引用内容已不可见</text><template v-else>{{ row.quoted.floor }}楼 · {{ row.quoted.authorName }}<view>{{ row.quoted.content }}</view><PhotoGridMobile :photos="row.quoted.photos || []"/><ForumAudioMobile :active="active !== false" v-if="row.quoted.audio" :attachment="row.quoted.audio"/></template></view><view class="prose topic-body">{{ row.status === 'deleted' ? '此层回复已删除' : row.content }}</view><PhotoGridMobile :photos="row.photos || []"/><ForumAudioMobile :active="active !== false" v-if="row.audio && row.status !== 'deleted'" :attachment="row.audio"/><view class="button-row"><button v-if="row.status === 'approved' && !selected.locked" class="text-button" @click="quoted = row">引用回复</button><button v-if="row.status !== 'deleted' && (row.authorId === user?.id || row.canModerate)" class="text-button" @click="ask(row,'delete','replies')">删除</button><button v-if="row.canModerate && row.status === 'approved'" class="text-button" @click="ask(row,'hidden','replies')">隐藏</button><button v-if="user?.status === 'approved' && row.authorId !== user.id" class="text-button" @click="ask(row,'block')">拉黑</button><button v-if="row.canModerate" class="text-button" @click="ask(row,'mute')">禁言</button></view></view><view v-if="selected.status === 'approved' && !selected.locked" class="form-page"><view v-if="quoted" class="quoted-post">回复 {{ quoted.floor }}楼 · {{ quoted.authorName }}<text @click="quoted = null"> 取消引用 ×</text></view><view class="field"><text class="field-label">发表回复</text><textarea v-model="reply" maxlength="2000" placeholder="友善交流，认真回应"/></view><PhotoFieldMobile :key="selected.id + replies.length" v-model="replyPhotos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioFieldMobile :key="selected.id" v-model="replyAudio" :user-id="user?.id" @busy="audioUploading = $event"/><button class="primary" :disabled="busy || audioUploading || photosPending" @click="user?.status === 'approved' ? respond() : emit('join')">提交回复</button></view><view v-else class="notice-line">话题暂不接受新回复</view></template>
<template v-else><button v-if="!embedded" class="primary" @click="newTopic()">＋ 发起话题</button><scroll-view scroll-x class="forum-strip-scroll"><view class="pill-row forum-tabs"><text :class="['pill',{ active: tab === 'public' }]" @click="tab = 'public'">全部话题</text><text :class="['pill',{ active: tab === 'hot' }]" @click="tab = 'hot'">热帖</text><text v-if="user" :class="['pill',{ active: tab === 'mine' }]" @click="tab = 'mine'">我的发布</text><text v-if="moderator" :class="['pill',{ active: tab === 'manage' }]" @click="tab = 'manage'">版主管理</text><text v-if="moderator" :class="['pill',{ active: tab === 'restrictions' }]" @click="tab = 'restrictions'">板块限制</text><text v-if="user" :class="['pill',{ active: tab === 'blocks' }]" @click="tab = 'blocks'">黑名单</text></view></scroll-view>
<template v-if="['public','hot','mine'].includes(tab)"><view v-if="tab === 'hot'" class="safe-note">管理人员推荐的热帖，置顶优先，其余按公开回复数和发布时间排列。</view><view class="forum-list-filters" :class="{ 'forum-railway-filters': railwayMode }">
  <scroll-view v-if="!lockedBoard" scroll-x class="forum-strip-scroll"><view class="pill-row forum-category-strip"><text v-for="item in ['全部',...forumCategories]" :key="item" :class="['pill',{ active: category === item }]" @click="category = item">{{ item }}</text></view></scroll-view>
  <scroll-view v-if="railwayMode" scroll-x class="forum-strip-scroll"><view class="pill-row forum-category-strip" aria-label="高铁话题类型"><button v-for="item in ['全部',...railwayDiscussionTypes]" :key="item" :class="['pill',{ active: discussionType === item }]" :aria-pressed="discussionType === item" @click="discussionType = item">{{ item }}</button></view></scroll-view>
  <view class="forum-list-tools"><input v-model="query" class="search" aria-label="搜索话题" placeholder="搜索话题、内容、老乡"/><picker v-if="railwayMode" class="forum-sort" :range="sortOptions" range-key="label" :value="sortOptions.findIndex(item => item.id === sort)" aria-label="排列方式" @change="changeSort"><view class="picker-value">{{ sortOptions.find(item => item.id === sort)?.label }} ▾</view></picker></view>
</view><view v-if="!visible.length" class="empty">{{ tab === 'hot' ? '当前筛选下暂无热帖，可切换板块或查看全部话题。' : '当前筛选下暂无话题，可以调整筛选或发起话题。' }}</view><view v-for="row in visible" :key="row.id" class="panel topic-row forum-topic" @click="row.status !== 'deleted' && detail(row)">
  <view class="forum-topic-tags"><text v-if="!lockedBoard" class="tag">{{ row.category }}</text><text v-if="row.category === RAILWAY_BOARD" class="tag forum-type">{{ row.discussionType || railwayDiscussionTypes[0] }}</text><text v-if="row.pinned && row.status === 'approved'" class="tag promotion-pin">置顶</text><text v-if="row.hot && row.status === 'approved'" class="tag promotion-hot">热帖</text><text v-if="row.status !== 'approved' || tab === 'mine'" class="forum-topic-state">{{ statusNames[row.status] }}</text><text v-if="row.locked" class="forum-topic-state">已关闭回复</text></view>
  <view class="card-title forum-topic-title">{{ row.title }}</view>
  <view class="post-excerpt forum-topic-excerpt">{{ row.content || (row.photos?.length ? row.photos.length + ' 张照片 · 点击查看' : row.audio ? '语音话题 · 点击收听' : '') }}</view>
  <view class="row forum-topic-meta"><text class="meta forum-topic-byline">{{ row.authorName }} · {{ formatTime(row.createdAt) }}</text><text class="meta forum-topic-replies">{{ row.replyCount }} 条回复</text></view>
</view></template>
<template v-if="tab === 'manage'"><button class="outline" :disabled="busy" @click="load">刷新话题</button><button v-if="focused" class="outline" @click="focused = null">查看全部管理内容</button><view class="safe-note">每个板块最多置顶3条公开话题，热帖由管理人员推荐。版主只可管理被分配的板块。隐藏可恢复，删除清空正文。</view><template v-for="section in [{ title: '话题管理', rows: focusRows(managed,'forum_topic'), kind: 'topics' },{ title: '回复管理', rows: focusRows(managedReplies,'forum_reply'), kind: 'replies' }]" :key="section.kind"><view class="section-title">{{ section.title }}</view><view v-if="!section.rows.length" class="empty">暂无内容</view><view v-for="row in section.rows" :key="row.id" class="panel"><text class="tag">{{ row.category }} · {{ statusNames[row.status] }}</text><text v-if="row.pinned && row.status === 'approved'" class="tag promotion-pin">置顶</text><text v-if="row.hot && row.status === 'approved'" class="tag promotion-hot">热帖</text><view class="card-title">{{ row.title || row.authorName + '的回复' }}</view><view class="prose topic-body">{{ row.content }}</view><PhotoGridMobile :photos="row.photos || []"/><ForumAudioMobile :active="active !== false" v-if="row.audio" :attachment="row.audio"/><view class="button-row"><button v-if="row.status === 'pending' || row.status === 'hidden'" class="primary small" @click="ask(row,'approved',section.kind)">{{ row.status === 'hidden' ? '恢复展示' : '审核通过' }}</button><button v-if="row.status === 'pending'" class="outline small" @click="ask(row,'rejected',section.kind)">退回</button><template v-if="section.kind === 'topics' && row.status === 'approved'"><button class="text-button" :disabled="busy" @click="ask(row,row.pinned ? 'unpin' : 'pin')">{{ row.pinned ? '取消置顶' : '置顶话题' }}</button><button class="text-button" :disabled="busy" @click="ask(row,row.hot ? 'unhot' : 'hot')">{{ row.hot ? '取消热帖' : '设为热帖' }}</button></template><button v-if="row.status === 'approved'" class="outline small" @click="ask(row,'hidden',section.kind)">隐藏</button><button v-if="row.status !== 'deleted'" class="text-button" @click="ask(row,'delete',section.kind)">删除</button><button class="text-button" @click="ask(row,'mute')">禁言作者</button><button class="text-button" @click="ask(row,'kick')">移出版块</button></view></view></template></template>
<template v-if="tab === 'restrictions'"><view class="safe-note">移出后限制账号参与该板块；公开内容仍可由访客浏览。</view><view v-if="!restrictions.length" class="empty">暂无板块限制</view><view v-for="row in restrictions" :key="row.id" class="panel"><view class="card-title">{{ row.name }} · {{ row.board }}</view><view class="meta">{{ row.action === 'kick' ? '已移出' : '已禁言' }} · {{ row.reason }}</view><button class="outline small" @click="ask(row,'restore')">恢复参与</button></view></template>
<template v-if="tab === 'blocks'"><view class="safe-note">拉黑后隐藏对方论坛内容，禁止新的私聊与联系方式交换请求。</view><view v-if="!blocks.length" class="empty">黑名单为空</view><view v-for="row in blocks" :key="row.id" class="panel row"><text>{{ row.name }}</text><button class="outline small" @click="ask(row,'unblock')">取消拉黑</button></view></template></template></view></template>
<style scoped>
